import linecache
from importlib.machinery import ModuleSpec

class FakeLoader:

    def get_source(self, fullname):
        return f'source for {fullname}'

class NoSourceLoader:

    def get_source(self, fullname):
        return None

def _t():
    filename = 'scheme://path'
    for loader in (None, object(), NoSourceLoader()):
        linecache.clearcache()
        module_globals = {'__name__': 'a.b.c', '__loader__': loader}
        assert linecache.getlines(filename, module_globals) == [], ('assertEqual', linecache.getlines(filename, module_globals), [])
    linecache.clearcache()
    module_globals = {'__name__': 'a.b.c', '__loader__': FakeLoader()}
    assert linecache.getlines(filename, module_globals) == ['source for a.b.c\n'], ('assertEqual', linecache.getlines(filename, module_globals), ['source for a.b.c\n'])
    for spec in (None, object(), ModuleSpec('', FakeLoader())):
        linecache.clearcache()
        module_globals = {'__name__': 'a.b.c', '__loader__': FakeLoader(), '__spec__': spec}
        assert linecache.getlines(filename, module_globals) == ['source for a.b.c\n'], ('assertEqual', linecache.getlines(filename, module_globals), ['source for a.b.c\n'])
    linecache.clearcache()
    spec = ModuleSpec('x.y.z', FakeLoader())
    module_globals = {'__name__': 'a.b.c', '__loader__': spec.loader, '__spec__': spec}
    assert linecache.getlines(filename, module_globals) == ['source for x.y.z\n'], ('assertEqual', linecache.getlines(filename, module_globals), ['source for x.y.z\n'])
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')

